ee:message.ee:set-payload:
%dw 2.0
output application/json
var errorBody = error.cause.errorMessage.payload default {}
var sapiError = if (errorBody is Object and errorBody.status?) errorBody else null
---
if (sapiError != null) 
	sapiError
else {
	"status": vars.httpStatus,
	"code": error.errorType.identifier default "CLIENT_ERROR",
	"message": {
		"message": if (errorBody is String and !isEmpty(errorBody)) 
					errorBody 
				   else 
					error.description default "Error en la solicitud al servicio LISIM"
	},
	"messageServer": error.description default "",
	"cause": [
		{
			"origin": "customer-papi-services",
			"message": "Error en llamada a lisim-sapi-services: " ++ (error.errorType.identifier default "HTTP_CLIENT_ERROR")
		}
	]
}

%dw 2.0
output application/json
var errorBody = error.cause.errorMessage.payload default {}
var sapiError = if (errorBody is Object and errorBody.status?) errorBody else null
---
if (sapiError != null) 
	sapiError
else {
	"status": vars.httpStatus,
	"code": if (vars.httpStatus == 503) "SERVICE_UNAVAILABLE" 
			else if (vars.httpStatus == 504) "GATEWAY_TIMEOUT"
			else "LISIM_SAPI_ERROR",
	"message": {
		"message": if (errorBody is String and !isEmpty(errorBody)) 
					errorBody 
				   else if (vars.httpStatus == 503)
					"El servicio de validación de riesgo no está disponible temporalmente. Por favor intente más tarde."
				   else if (vars.httpStatus == 504)
					"Tiempo de espera agotado al conectar con el servicio de validación de riesgo."
				   else 
					"Error en el servicio de validación de riesgo LISIM."
	},
	"messageServer": error.description default "",
	"cause": [
		{
			"origin": "customer-papi-services",
			"message": "Error en llamada a lisim-sapi-services: " ++ (error.errorType.identifier default "HTTP_SERVER_ERROR")
		}
	]
}

%dw 2.0
output application/json
var isTimeout = (error.errorType.identifier default "") contains "TIMEOUT"
---
{
	"status": 503,
	"code": if (isTimeout) "TIMEOUT" else "SERVICE_UNAVAILABLE",
	"message": {
		"message": if (isTimeout) 
					"Tiempo de espera agotado al conectar con el servicio de validación de riesgo. Por favor intente nuevamente."
				   else 
					"No fue posible conectar con el servicio de validación de riesgo. Por favor intente más tarde."
	},
	"messageServer": error.description default "",
	"cause": [
		{
			"origin": "customer-papi-services",
			"message": "Error de conectividad con lisim-sapi-services: " ++ (error.errorType.identifier default "CONNECTIVITY_ERROR")
		}
	]
}

%dw 2.0
output application/json
---
{
	"status": 500,
	"code": "PARSING_ERROR",
	"message": {
		"message": "Error procesando la respuesta del servicio de validación de riesgo."
	},
	"messageServer": error.description default "",
	"cause": [
		{
			"origin": "customer-papi-services",
			"message": "Error de parsing en respuesta de lisim-sapi-services: " ++ (error.errorType.identifier default "PARSING_ERROR")
		}
	]
}

%dw 2.0
output application/json
var errorBody = error.cause.errorMessage.payload default {}
---
{
	"status": 500,
	"code": "INTERNAL_SERVER_ERROR",
	"message": {
		"message": if (errorBody is String and !isEmpty(errorBody)) 
					errorBody 
				   else 
					"Error inesperado en el servicio de validación de riesgo."
	},
	"messageServer": error.description default "",
	"cause": [
		{
			"origin": "customer-papi-services",
			"message": "Error inesperado en llamada a lisim-sapi-services: " ++ (error.errorType.identifier default "UNKNOWN_ERROR")
		}
	]
}
